mapper.select:
SELECT COALESCE(SUM(bd.remaining), 0)

FROM points_batch AS pb,
     JSON_TABLE(
             pb.batch_detail,
             '$[*]' COLUMNS (
                 expire_date DATE PATH '$.expire_date',
                 remaining INT UNSIGNED PATH '$.remaining'
                 )
     ) AS bd

WHERE pb.is_deleted = 0
  AND pb.remaining_points > 0
  AND pb.owner_id = #{ownerId}
  AND pb.owner_type = #{ownerType}
  AND pb.first_expire_date BETWEEN #{startTime} AND #{endTime}
  AND bd.remaining > 0
  AND bd.expire_date BETWEEN #{startTime} AND #{endTime}
